		every_system = {
			limit = {
				NOR = {
					is_star_class = sc_black_hole
					is_star_class = sc_neutron_star
					is_star_class = sc_pulsar
				}
			}
			every_system_planet = {
				limit = {
					OR = {
						is_planet_class = pc_barren
						is_planet_class = pc_barren_cold
					}
					NOR = {
						has_deposit = d_nanites_deposit
						has_anomaly = yes
						has_modifier = terraforming_candidate
					}
					planet_size > 9
					planet_size < 31
				}
				random_list = {
					100 = {}
					1 = { #about 20 on a huge galaxy with default settings.
						add_modifier = { modifier = terraforming_candidate }
						complex_trigger_modifier = {
							trigger = check_galaxy_setup_value
							parameters = {
								setting = habitable_worlds_scale
							}
							mode = factor
						}
					}
				}
			}
			if = {
				limit = { host_has_dlc = "Aquatics Species Pack" }
				every_system_planet = {
					limit = {
						is_planet_class = pc_frozen
						NOR = {
							has_deposit = d_nanites_deposit
							has_anomaly = yes
							has_modifier = frozen_terraforming_candidate
						}
						planet_size > 9
						planet_size < 31
					}
					random_list = {
						100 = {}
						1 = { #Not very common, Hydrocentric gives you lots of other things
							add_modifier = { modifier = frozen_terraforming_candidate }
							complex_trigger_modifier = {
								trigger = check_galaxy_setup_value
								parameters = {
									setting = habitable_worlds_scale
								}
								mode = factor
							}
						}
					}
				}
			}
			if = {
				limit = { host_has_dlc = "Toxoids Species Pack" }
				every_system_planet = {
					limit = {
						is_planet_class = pc_toxic
						NOR = {
							has_deposit = d_nanites_deposit
							has_anomaly = yes
							has_modifier = toxic_terraforming_candidate
						}
						planet_size > 9
						planet_size < 31
					}
					random_list = {
						100 = {}
						15 = { #Detox only gives you this. About 50 planets in a huge galaxy
							add_modifier = { modifier = toxic_terraforming_candidate }
							set_carrier_flag = toxic_terraforming_candidate
							complex_trigger_modifier = {
								trigger = check_galaxy_setup_value
								parameters = {
									setting = habitable_worlds_scale
								}
								mode = factor
							}
						}
					}
				}
			}
		}
		every_galaxy_planet = {
			limit = {
				is_planet_class = pc_nuked
			}
			set_carrier_flag = ancient_history_planet
		}
		# Polytechnic Districts are rare, but shouldnt be > 2
		every_galaxy_planet = {
			limit = {
				is_planet_class = pc_volcanic
			}
			if = {
				limit = {
					check_modifier_value = {
						modifier = district_polytechnic_max_add
						value < 2
					}
				}
				add_deposit = d_volcanic_basalt_plains
			}
		}
		every_system = {
			limit = {
				has_owner = no
			}
			every_system_planet = {
				limit = {
					colonizable_planet = yes
					has_owner = no
					AND = {
						NOT = { is_same_value = event_target:sol_system_earth? }
						NOT = { has_carrier_flag = prescripted_ideal }
						NOT = { has_carrier_flag = ratling_planet }
						NOT = { has_carrier_flag = pre_sapients_forbidden }
					}
				}
				save_event_target_as = pre_sapient_planet
				random_list = {
					100 = {
						modifier = {
							subtract = value:presapient_spawn_chance
						}
					}
					0 = { # 7.5% chance at 1x on the slider.
						spawn_presapient_species_randomizer_effect = yes
						modifier = {
							add = value:presapient_spawn_chance
						}
					}
				}
			}
		}
		if = {
			limit = {
				any_system = {
					has_star_flag = old_foes_system
				}
			}
			random_system = {
				limit = {
					has_star_flag = old_foes_system
				}
				spawn_old_foes_effect = yes
			}
		}
	}
}

