country_event = {
	id = game_start.9
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		#science
		if = {
			limit = { is_low_tech_start = no }

			create_fleet = {
				effect = {
					set_owner = prev

					create_ship = {
						name = random
						random_existing_design = science
					}

					set_fleet_stance = evasive
					#set_location = prev.capital_star
					set_location = prev.capital_scope.star

					owner = {
						create_leader = {
							class = scientist
							sub_type = survey
							name = random
							species = owner_main_species
							randomize_traits = no
							traits = {
								1 = random_common
							}
						}
					}
					set_leader = last_created_leader
				}
			}
		}
		else_if = {
			limit = {
				has_origin = origin_payback
			}
			create_leader = {
				class = scientist
				name = random
				species = owner_main_species
				randomize_traits = no
				traits = {
					1 = random_common
				}
			}
		}

		if = {
			limit = {
				is_eager_explorer_empire = yes
			}
			while = {
				count = 2
				create_fleet = {
					effect = {
						set_owner = prev

						create_ship = {
							name = random
							random_existing_design = explorer_vessel
						}

						set_fleet_stance = passive
						set_location = prev.capital_scope.star

						owner = {
							create_leader = {
								class = scientist
								sub_type = survey
								name = random
								species = owner_main_species
								randomize_traits = no
								traits = {
									1 = random_common
								}
							}
						}
						if = {
							limit = {
								NOT = { root =  { has_country_flag = created_first_eager_ship } }
							}
							root = {
								set_country_flag = created_first_eager_ship
							}
							last_created_leader = {
								add_trait = {
									trait = leader_trait_meticulous
									show_message = no
								}
							}
						}
						else = {
							last_created_leader = {
								add_trait = {
									trait = leader_trait_roamer
									show_message = no
								}
							}
						}
						set_leader = last_created_leader
					}
				}
			}
		}

		if = {
			limit = {
				has_civic = civic_privatized_exploration
			}
			random_owned_starbase = {
				set_starbase_size = starbase_starhold
				set_starbase_module = {
					slot = 2
					module = shipyard
				}
				set_starbase_module = {
					slot = 3
					module = trading_hub
				}
				set_starbase_module = {
					slot = 4
					module = trading_hub
				}
				set_starbase_building = {
					slot = 2
					building = resource_silo
				}
			}
		}

		if = {
			limit = {
				has_origin = origin_mindwardens
			}
			random_owned_starbase = {
				set_starbase_size = starbase_starhold
				set_starbase_module = {
					slot = 3
					module = gun_battery
				}
				set_starbase_module = {
					slot = 4
					module = gun_battery
				}
				set_starbase_building = {
					slot = 2
					building = resource_silo
				}
			}
		}

		#constructor
		if = {
			limit = {
				is_low_tech_start = no
				is_nomadic = no
			}

			create_fleet = {
				effect = {
					set_owner = prev

					create_ship = {
						name = random
						random_existing_design = constructor
					}

					set_fleet_stance = evasive
					set_location = prev.capital_star
				}
			}
		}

		if = {
			limit = {
				is_low_tech_start = no
				is_nomadic = yes
			}

			create_fleet = {
				effect = {
					set_owner = prev

					create_ship = {
						name = random
						random_existing_design = nomads_constructor
					}

					set_fleet_stance = evasive
					set_location = prev.capital_star
				}
			}
			if = {
				limit = {
					has_origin = origin_default_nomads
				}
				create_fleet = {
					effect = {
						set_owner = prev

						create_ship = {
							name = random
							random_existing_design = nomads_constructor
						}

						set_fleet_stance = evasive
						set_location = prev.capital_star
					}
				}
			}
		}

		if = {
			limit = {
				is_eager_explorer_empire = yes
				is_nomadic = no
			}
			create_fleet = {
				effect = {
					set_owner = prev

					create_ship = {
						name = random
						random_existing_design = engineer_vessel
					}

					set_fleet_stance = evasive
					set_location = prev.capital_star
				}
			}
		}

		if = {
			limit = {
				is_eager_explorer_empire = yes
				is_nomadic = yes
			}
			create_fleet = {
				effect = {
					set_owner = prev

					create_ship = {
						name = random
						random_existing_design = nomads_engineer_vessel
					}

					set_fleet_stance = evasive
					set_location = prev.capital_star
				}
			}
			if = {
				limit = {
					has_origin = origin_default_nomads
				}
				create_fleet = {
					effect = {
						set_owner = prev

						create_ship = {
							name = random
							random_existing_design = nomads_engineer_vessel
						}

						set_fleet_stance = evasive
						set_location = prev.capital_star
					}
				}
			}
		}

		# Beastmaster Amboebas
		if = {
			limit = {
				is_beastmasters_empire = yes
			}
			# required before trying to give space fauna
			give_dna = {
				ship_category = space_amoeba
				rarity = common
			}
			if = {
				limit = {
					is_nomadic = no
				}
				create_fleet = {
					effect = {
						set_owner = prev
						while = {
							count = 3
							create_ship = {
								name = random
								random_existing_design = space_amoeba
								rarity = common
								age = 0
							}
						}
						set_location = prev.capital_star
						owner = {
							create_leader = {
								class = commander
								name = random
								species = owner_main_species
								randomize_traits = no
								traits = {
									1 = random_common
								}
							}
						}
						set_leader = last_created_leader
						save_event_target_as = beastmasters_starting_fleet
					}
				}
			}

			if = {
				limit = { has_origin = origin_fruitful }
				event_target:beastmasters_starting_fleet = {
					fleet_event = {
						id = origin.7303
						days = 20
						scopes = {
							from = prev.capital_star.starbase
						}
					}
				}
			}
		}

		# Regular corvettes/maulers
		else_if = {
			limit = {
				is_nomadic = no
				is_low_tech_start = no
			}

			create_fleet = {
				effect = {
					set_owner = prev
					set_location = prev.capital_star
					if = {
						limit = {
							root = {
								country_uses_bio_ships = yes
								NOT = {
									has_valid_civic = civic_hive_cordyceptic_drones
								}
							}
						}
						while = {
							count = 2
							create_ship = {
								name = random
								random_existing_design = mauler_stage_1
							}
						}
						if = {
							limit = {
								root = { has_origin = origin_progenitor_hive }
							}
							create_ship = {
								name = random
								random_existing_design = offspring_weaver_stage_1
							}
						}
						else = {
							create_ship = {
								name = random
								random_existing_design = weaver_stage_1
							}
						}
					}
					else_if = {
						limit = {
							root = {
								NOT = {
									has_valid_civic = civic_hive_cordyceptic_drones
								}
							}
						}
						while = {
							count = 2
							create_ship = {
								name = random
								random_existing_design = corvette
							}
						}
						if = {
							limit = {
								root = { has_origin = origin_progenitor_hive }
							}
							create_ship = {
								name = random
								random_existing_design = offspring_corvette
							}
						}
						else = {
							create_ship = {
								name = random
								random_existing_design = corvette
							}
						}
					}
					else = {
						while = {
							count = 2
							create_ship = {
								name = NAME_Reanimated_Small_Space_Organism
								design = NAME_Reanimated_Small_Space_Organism
								prefix = yes
							}
						}
						if = {
							limit = {
								root = {
									country_uses_bio_ships = no
									has_origin = origin_progenitor_hive
								}
							}
							create_ship = {
								name = random
								random_existing_design = offspring_corvette
							}
						}
						else_if = {
							limit = {
								root = {
									country_uses_bio_ships = yes
									has_origin = origin_progenitor_hive
								}
							}
							create_ship = {
								name = random
								random_existing_design = offspring_weaver_stage_1
							}
						}
						else = {
							create_ship = {
								name = "NAME_Reanimated_Small_Space_Organism"
								design = NAME_Reanimated_Small_Space_Organism
								prefix = yes
							}
						}
					}
					owner = {
						create_leader = {
							class = commander
							name = random
							species = owner_main_species
							randomize_traits = no
							traits = {
								1 = random_common
							}
						}
					}
					set_leader = last_created_leader
				}
			}
		}

		# Reanimated Amboebas
		else_if = {
			limit = {
				is_nomadic = no
				has_civic = civic_hive_cordyceptic_drones
				has_civic = civic_hive_stargazers
			}
			create_fleet = {
				set_take_point = yes
				effect = {
					set_owner = prev
					while = {
						count = 3
						create_ship = {
							name = NAME_Reanimated_Small_Space_Organism
							design = NAME_Reanimated_Small_Space_Organism
