country_event = {
	id = game_start.60
	hide_window = yes
	trigger = {
		is_country_type = default
		#selectable = { host_has_dlc = "Galactic Paragons" }
	}

	is_triggered_only = yes

	immediate = {
		set_variable = {
			which = paragon_chance_negative
			value = 0
		}

		# Give Empire the starting Council Agenda.
		# Nomadic empires start halfway through the arkship engineering agenda.
		# All other empires are progressed to about 1-2 years from finishing agenda_infinite_opportunities.
		if = {
			limit = { is_nomadic = yes }
			if = {
				limit = { has_country_flag = starting_civilian_arkship }
				set_council_agenda = agenda_arkship_engineering_civilian
				add_council_agenda_progress = 3500
			}
			else_if = {
				limit = { has_country_flag = starting_science_arkship }
				set_council_agenda = agenda_arkship_engineering_science
				add_council_agenda_progress = 3500
			}
			else_if = {
				limit = { has_country_flag = starting_military_arkship }
				set_council_agenda = agenda_arkship_engineering_military
				add_council_agenda_progress = 3500
			}
			# Failsafe just in case.
			else = {
				if = {
					limit = { is_gestalt = yes }
					set_council_agenda = agenda_infinite_opportunities_gestalt
				}
				else = {
					set_council_agenda = agenda_infinite_opportunities
				}
				add_council_agenda_progress = 6000
			}
		}
		else_if = {
			limit = { is_gestalt = yes }
			set_council_agenda = agenda_infinite_opportunities_gestalt
			add_council_agenda_progress = 6000
		}
		else = {
			set_council_agenda = agenda_infinite_opportunities
			add_council_agenda_progress = 6000
		}
	}
}

