						DISTANCE = 9.899
					}
					event_target:target_habitat = {
						set_carrier_flag = void_dweller_advanced_t2_habitat
					}
				}
				create_advanced_empire_system_stations_effect = {
					OWNER = root
				}
			}
		}
	}
