script:
colony_event = {
	id = game_start.130
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		owner? = {
			is_nomadic = yes
		}
	}

	immediate = {
		set_timed_carrier_flag = {
			flag = ignore_ai_building_limitations
			days = 1
		}

		owner = {
			if = {
				limit = {
					NOT = {
						has_technology = tech_planetary_engineering
					}
				}
				give_technology = {
					tech = tech_planetary_engineering
					message = no
				}
			}
		}

		# Upgrade capital Arkship to tier 2
		fleet = {
			starbase? = {
				switch = {
					trigger = is_ship_size
					civilian_arkship_tier_1 = {
						set_starbase_size = civilian_arkship_tier_2
					}
					science_arkship_tier_1 = {
						set_starbase_size = science_arkship_tier_2
					}
					military_arkship_tier_1 = {
						set_starbase_size = military_arkship_tier_2
					}
				}
			}
		}

		if = {
			limit = {
				is_capital = yes
			}
			add_advanced_empire_arkship_capital_districts_effect = yes
		}
		else = {
			add_advanced_empire_arkship_colony_districts_effect = yes
			add_advanced_empire_colony_buildings_effect = yes
		}
		add_advanced_empire_capital_pops_effect = yes
	}
}

country_event = {
	id = game_start.135
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		is_nomadic = yes
	}

	immediate = {
		advanced_empire_base_init_effect = yes
		give_technology = {
			tech = tech_arkship_construction
			message = no
		}

		# Capital system waystation. Creates one if none exists, or upgrades an existing one (e.g. Caravan Masters).
		capital_scope = {
			solar_system = {
				if = {
					limit = {
						NOT = {
							any_fleet_in_system = {
								is_waystation_ship = yes
							}
						}
					}
					create_waystation_effect = {
						OWNER = root
						ANGLE = 120
					}
				}
				else = {
					random_fleet_in_system = {
						limit = {
							is_waystation_ship = yes
							owner = {
								is_same_value = root
							}
						}
						starbase? = {
							set_starbase_size = starbase_waystation_2
						}
					}
				}
			}
		}

		# Research system
		closest_system = {
			limit = {
				has_star_flag = neighbor_t1_first_colony
			}
			max_steps = 3
			save_event_target_as = advanced_nomad_t1_system
			convert_to_research_system_effect = yes
			set_surveyed = {
				surveyed = yes
				surveyor = root
			}
			create_waystation_effect = {
				OWNER = root
				ANGLE = 120
			}
			random_ship_in_system = {
				limit = {
					is_waystation_ship = yes
					owner = {
						is_same_value = root
					}
				}
				starbase = {
					if = {
						limit = {
							solar_system = {
								# This should always be true, but as a failsafe.
								any_system_planet = {
									has_deposit_for = shipclass_research_station
								}
							}
						}
						set_starbase_module = {
							slot = 1
							module = waystation_research_module
						}
					}
				}
			}
		}
		capital_scope = {
			ship = {
				if = {
					limit = { is_civilian_arkship = yes }
					create_arkship_effect = {
						TYPE = civilian_arkship
						OWNER = root
						LOCATION = event_target:advanced_nomad_t1_system
					}
				}
				else_if = {
					limit = { is_science_arkship = yes }
					create_arkship_effect = {
						TYPE = science_arkship
						OWNER = root
						LOCATION = event_target:advanced_nomad_t1_system
					}
				}
				else_if = {
					limit = { is_military_arkship = yes }
					create_arkship_effect = {
						TYPE = military_arkship
						OWNER = root
						LOCATION = event_target:advanced_nomad_t1_system
					}
				}
			}
		}
		random_owned_colony = {
			limit = {
				solar_system = {
					is_same_value = event_target:advanced_nomad_t1_system
				}
			}
			colony_event = {
				id = game_start.21
			}
			add_advanced_empire_arkship_colony_districts_effect = yes
			add_advanced_empire_colony_buildings_effect = yes
		}

		# Resource system
		closest_system = {
			limit = {
				has_star_flag = neighbor_t2_second_colony
			}
			max_steps = 6
			save_event_target_as = advanced_nomad_t2_system
			convert_to_resource_system_effect = yes
			set_surveyed = {
				surveyed = yes
				surveyor = root
			}
			create_waystation_effect = {
				OWNER = root
				ANGLE = 120
			}
			random_ship_in_system = {
				limit = {
					is_waystation_ship = yes
					owner = {
						is_same_value = root
					}
				}
				starbase = {
					if = {
						limit = {
							solar_system = {
								# This should always be true, but as a failsafe.
								any_system_planet = {
									has_deposit_for = shipclass_mining_station
								}
							}
						}
						set_starbase_module = {
							slot = 1
							module = waystation_mining_module
						}
					}
				}
			}
		}
		capital_scope = {
			ship = {
				if = {
					limit = { is_civilian_arkship = yes }
					create_arkship_effect = {
						TYPE = civilian_arkship
						OWNER = root
						LOCATION = event_target:advanced_nomad_t2_system
					}
				}
				else_if = {
					limit = { is_science_arkship = yes }
					create_arkship_effect = {
						TYPE = science_arkship
						OWNER = root
						LOCATION = event_target:advanced_nomad_t2_system
					}
				}
				else_if = {
					limit = { is_military_arkship = yes }
					create_arkship_effect = {
						TYPE = military_arkship
						OWNER = root
						LOCATION = event_target:advanced_nomad_t2_system
					}
				}
			}
		}
		random_owned_colony = {
			limit = {
				solar_system = {
					is_same_value = event_target:advanced_nomad_t2_system
				}
			}
			colony_event = {
				id = game_start.21
			}
			add_advanced_empire_arkship_colony_districts_effect = yes
			add_advanced_empire_colony_buildings_effect = yes
		}
	}
}
